import java.net.*;

class ServiceUnavailableException extends RuntimeException {
    ServiceUnavailableException(String msg, Throwable cause) { super(msg, cause); }
}

// simulates an HTTP client with separate connect and read timeouts
class HttpClient {
    long connectTimeoutMs;
    long readTimeoutMs;

    HttpClient(long connectTimeoutMs, long readTimeoutMs) {
        this.connectTimeoutMs = connectTimeoutMs;
        this.readTimeoutMs = readTimeoutMs;
    }

    String send(boolean simulateConnectFailure) throws Exception {
        if (simulateConnectFailure) {
            throw new ConnectException("connection refused after " + connectTimeoutMs + "ms");
        }
        return "response body";
    }
}

public class Main {
    public static void main(String[] args) {
        HttpClient httpClient = new HttpClient(3000, 10000);

        try {
            String resp = httpClient.send(true);
            System.out.println(resp);
        } catch (Exception e) {
            System.out.println("Connection timed out: " + e.getMessage());
            throw new ServiceUnavailableException("Upstream unreachable", e);
        }
    }
}

