import java.util.concurrent.*;

class GatewayTimeoutException extends RuntimeException {
    GatewayTimeoutException(String msg) { super(msg); }
}

class PaymentResult {
    String status;
    PaymentResult(String status) { this.status = status; }
}

class Gateway {
    PaymentResult charge(long accountId, double amount) throws InterruptedException {
        Thread.sleep(8000);   // simulates a slow downstream call
        return new PaymentResult("charged");
    }
}

class PaymentService {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Gateway gateway = new Gateway();

    PaymentResult chargeWithDeadline(long accountId, double amount) throws Exception {
        Future<PaymentResult> future = executor.submit(() -> gateway.charge(accountId, amount));
        try {
            // overall deadline, regardless of connect/read timeouts
            return future.get(1, TimeUnit.SECONDS);
        } catch (TimeoutException e) {
            future.cancel(true);
            throw new GatewayTimeoutException("Payment deadline exceeded");
        } finally {
            executor.shutdownNow();
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        PaymentService service = new PaymentService();
        try {
            PaymentResult result = service.chargeWithDeadline(1, 100.0);
            System.out.println(result.status);
        } catch (GatewayTimeoutException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}

