class AdaptiveTimeout {
    private final Histogram latencyHistogram;
    private final double multiplier;
    private final Duration minTimeout, maxTimeout;

    Duration compute() {
        // p99 of recent calls × safety multiplier
        long p99Ms = (long) latencyHistogram.percentile(99.0);
        long adaptive = (long) (p99Ms * multiplier);
        return Duration.ofMillis(
            Math.min(maxTimeout.toMillis(),
                     Math.max(minTimeout.toMillis(), adaptive))
        );
    }

    <T> T execute(Callable<T> action) throws Exception {
        Duration timeout = compute();
        return CompletableFuture.supplyAsync(action::call)
            .orTimeout(timeout.toMillis(), TimeUnit.MILLISECONDS)
            .get();
    }
}

