import concurrent.futures


class AdaptiveTimeout:
    def __init__(self, multiplier, min_timeout_ms, max_timeout_ms):
        self.recent_latencies_ms = []
        self.multiplier = multiplier
        self.min_timeout_ms = min_timeout_ms
        self.max_timeout_ms = max_timeout_ms

    def record_latency(self, ms):
        self.recent_latencies_ms.append(ms)

    def percentile_99(self):
        sorted_latencies = sorted(self.recent_latencies_ms)
        index = max(0, int(0.99 * len(sorted_latencies)) - 1)
        return sorted_latencies[index]

    def compute(self):
        # p99 of recent calls times a safety multiplier
        p99_ms = self.percentile_99()
        adaptive = p99_ms * self.multiplier
        return min(self.max_timeout_ms, max(self.min_timeout_ms, adaptive))

    def execute(self, action):
        timeout_ms = self.compute()
        with concurrent.futures.ThreadPoolExecutor() as executor:
            future = executor.submit(action)
