import java.util.concurrent.*;

class AdaptiveTimeout {
    List<Long> recentLatenciesMs = new ArrayList<>();
    double multiplier;
    long minTimeoutMs, maxTimeoutMs;

    AdaptiveTimeout(double multiplier, long minTimeoutMs, long maxTimeoutMs) {
