        // p99 of recent calls times a safety multiplier
        long p99Ms = percentile99();
        long adaptive = (long)(p99Ms * multiplier);
        return min(maxTimeoutMs, max(minTimeoutMs, adaptive));
    }

    template <typename Func>
    auto execute(Func action) -> decltype(action()) {
